import { toValue, type MaybeRefOrGetter } from 'vue'
import { useAsyncData, useNuxtApp, useState } from '#imports'
// Virtual module generated by this module's `setup()`; only resolvable inside a real Nuxt build.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { widgets as registry } from '#widgets/registry'
import type { WidgetMeta } from '../../../types'
import { sortWidgets } from '../../utils/sort'

/**
 * The widgets registered for an area, ordered and passed through the `widgets:filter` hook, as plain data
 * (the component itself is resolved by `<WidgetArea>`). `context` is whatever the host renders the area for
 * (e.g. `{ user }`) and is handed to the filter listeners. Same return shape as `useAsyncData`.
 */
export function useWidgets(area: string, context?: MaybeRefOrGetter<Record<string, unknown> | undefined>) {
  const nuxtApp = useNuxtApp()

  // Bumped by the access layer (`@frigear-nu/authorization`) when what the viewer may do changes (sign-in, sign-out), so the
  // filtered result is resolved again. Shared through `useState`: no dependency on that layer, `0` without one.
  const accessVersion = useState<number>('access:version', () => 0)

  return useAsyncData(() => `widgets:${area}:${accessVersion.value}`, async () => {
    const widgets: WidgetMeta[] = sortWidgets((registry[area] ?? []).map(({ component: _component, ...meta }: WidgetMeta & { component: unknown }) => meta))
    const ctx = { area, widgets, context: toValue(context) }
    await nuxtApp.callHook('widgets:filter', ctx)
    return ctx.widgets
  }, { watch: [accessVersion] })
}
